'use strict';
const $=id=>document.getElementById(id), slides=window.SLIDES, synth=window.speechSynthesis;
let current=0,voices=[],token=0,timer=null,activeUtterance=null,done={};
try{done=JSON.parse(localStorage.getItem('diabetes-speaking-done')||'{}')}catch{}
function stop(){token++;clearTimeout(timer);if(synth)synth.cancel();activeUtterance=null;document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));$('status').textContent='已停止。可點選句子重新播放。'}
function spoken(t){return t.replace(/\bHbA1c\b/g,'H B A one C').replace(/\bCGM\b/g,'C G M').replace(/\bGDM\b/g,'G D M').replace(/\bGMI\b/g,'G M I').replace(/\bAGP\b/g,'A G P').replace(/\bLLM\b/g,'L L M').replace(/\bAID\b/g,'A I D').replace(/\bAI\b/g,'A I').replace(/\bPDF\b/g,'P D F');}
function play(items){stop();if(!synth||!voices.length){$('status').textContent='目前找不到英文語音。請在裝置安裝英文聲音，或改用另一個瀏覽器。';return}const run=token;let p=0,rep=0;function next(){if(run!==token)return;if(p>=items.length){$('status').textContent='播放完成，換您說一次。';document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));return}const item=items[p];document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));if(item.el)item.el.classList.add('speaking');const u=new SpeechSynthesisUtterance(spoken(item.text));u.voice=voices.find(v=>v.voiceURI===$('voice').value)||voices[0];u.lang=u.voice.lang;u.rate=Number($('rate').value);activeUtterance=u;$('status').textContent=`播放 ${p+1}/${items.length} · 第 ${rep+1} 次 · ${u.rate}×`;u.onerror=e=>{if(run!==token)return;$('status').textContent='語音未能完成：'+e.error+'。請選另一個聲音再試。';};u.onend=()=>{if(run!==token)return;rep++;if(rep>=Number($('repeat').value)){p++;rep=0}if(p>=items.length){next();return}$('status').textContent='跟讀時間…';timer=setTimeout(next,Number($('gap').value)*1000)};synth.speak(u)}next()}
function addText(tag,text,parent,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;parent.append(el);return el}
function fillVoices(){if(!synth){$('status').textContent='此瀏覽器不支援語音合成。您仍可閱讀講稿。';return}const prior=$('voice').value;voices=synth.getVoices().filter(v=>/^en[-_]/i.test(v.lang));$('voice').replaceChildren();voices.forEach(v=>{const o=new Option(v.name+' · '+v.lang,v.voiceURI);$('voice').add(o)});if(voices.some(v=>v.voiceURI===prior))$('voice').value=prior;else {const preferred=voices.find(v=>v.lang==='en-US');if(preferred)$('voice').value=preferred.voiceURI}if(!voices.length)$('voice').add(new Option('等待裝置載入英文聲音…',''));}
function nav(){const q=$('search').value.toLowerCase();$('nav').replaceChildren();slides.forEach((s,i)=>{if(!(s.title+s.summary+s.body).toLowerCase().includes(q))return;const a=addText('a',`${done[s.n]?'✓ ':''}${String(s.n).padStart(2,'0')}  ${s.title}`,$('nav'),i===current?'active':'');a.href='#slide-'+s.n;if(i===current)a.setAttribute('aria-current','page')});$('progress').textContent=`已練習 ${Object.values(done).filter(Boolean).length} / ${slides.length} 頁`;}
function render(){stop();const m=location.hash.match(/^#slide-(\d+)$/);current=Math.min(50,Math.max(0,(m?Number(m[1]):1)-1));const s=slides[current];$('title').textContent=s.title;$('number').textContent=`SLIDE ${String(s.n).padStart(2,'0')} / 51`;$('summary').textContent=s.summary;$('key').textContent=s.key;$('zh').textContent=s.zh;$('stage').textContent=s.en.slice(s.body.length).trim();$('done').checked=!!done[s.n];$('script').replaceChildren();s.sentences.forEach(text=>{const b=addText('button',text,$('script'),'sentence');b.setAttribute('aria-label','播放：'+text);b.onclick=()=>play([{text,el:b}])});$('words').replaceChildren();s.words.forEach(w=>{const row=addText('div','',$('words'),'word');const b=addText('button','▶ '+w.word,row);b.lang='en';b.onclick=()=>play([{text:w.word}]);addText('small',w.category,row);addText('p',w.tip,row)});$('phrases').replaceChildren();s.phrases.forEach(p=>{const d=addText('div','',$('phrases'),'phrase');addText('del',p.long,d);addText('b',p.simple,d);addText('small',p.why,d)});$('prev').disabled=current===0;$('next').disabled=current===50;$('status').textContent='點一句即可聽示範。聽完後跟讀。';nav()}
$('search').oninput=nav;$('prev').onclick=()=>location.hash='slide-'+current;$('next').onclick=()=>location.hash='slide-'+(current+2);$('play').onclick=()=>{fillVoices();play(slides[current].sentences.map((text,i)=>({text,el:$('script').children[i]})))};$('keyplay').onclick=()=>play([{text:slides[current].key}]);$('stop').onclick=stop;$('done').onchange=()=>{done[slides[current].n]=$('done').checked;try{localStorage.setItem('diabetes-speaking-done',JSON.stringify(done))}catch{}nav()};['voice','rate','repeat','gap'].forEach(id=>$(id).addEventListener('change',stop));window.addEventListener('hashchange',render);window.addEventListener('pagehide',stop);if(synth)synth.addEventListener('voiceschanged',fillVoices);fillVoices();render();
